module EventHandlers
  @@events = {}

  # Add a named callback for the given event.
  def self.add(event, key, proc)
    @@events[event] = NamedEvent.new if !@@events.has_key?(event)
    @@events[event].add(key, proc)
  end

  # Remove a named callback from the given event.
  def self.remove(event, key)
    @@events[event]&.remove(key)
  end

  # Clear all callbacks for the given event.
  def self.clear(key)
    @@events[key]&.clear
  end

  # Trigger all callbacks from an Event if it has been defined.
  def self.trigger(event, *args)
    return @@events[event]&.trigger(*args)
  end
end

class NamedEvent
  def initialize
    @callbacks = {}
  end

  # Adds an event handler procedure from the event.
  def add(key, proc)
    @callbacks[key] = proc
  end

  # Removes an event handler procedure from the event.
  def remove(key)
    @callbacks.delete(key)
  end

  # Clears the event of event handlers.
  def clear
    @callbacks.clear
  end

  # Triggers the event and calls all its event handlers. Normally called only
  # by the code where the event occurred.
  def trigger(*args)
    @callbacks.each_value { |callback| callback.call(*args) }
  end
end

def initialize(species, level, owner = $player, withMoves = true, recheck_form = true)
  species_data = GameData::Species.get(species)
  @species          = species_data.species
  @form             = species_data.base_form
  @forced_form      = nil
  @time_form_set    = nil
  self.level        = level
  @steps_to_hatch   = 0
  heal_status
  @gender           = nil
  @shiny            = nil
  @ability_index    = nil
  @ability          = nil
  @nature           = nil
  @nature_for_stats = nil
  @item             = nil
  @mail             = nil
  @moves            = []
  reset_moves if withMoves
  @first_moves      = []
  @ribbons          = []
  @cool             = 0
  @beauty           = 0
  @cute             = 0
  @smart            = 0
  @tough            = 0
  @sheen            = 0
  @pokerus          = 0
  @name             = nil
  @happiness        = species_data.happiness
  @poke_ball        = :POKEBALL
  @markings         = []
  @iv               = {}
  @ivMaxed          = {}
  @ev               = {}
  GameData::Stat.each_main do |s|
    @iv[s.id]       = rand(IV_STAT_LIMIT + 1)
    @ev[s.id]       = 0
  end
  case owner
  when Owner
    @owner = owner
  when Player, NPCTrainer
    @owner = Owner.new_from_trainer(owner)
  else
    @owner = Owner.new(0, "", 2, 2)
  end
  @obtain_method    = 0   # Met
  @obtain_method    = 4 if $game_switches && $game_switches[Settings::FATEFUL_ENCOUNTER_SWITCH]
  @obtain_map       = ($game_map) ? $game_map.map_id : 0
  @obtain_text      = nil
  @obtain_level     = level
  @hatched_map      = 0
  @timeReceived     = Time.now.to_i
  @timeEggHatched   = nil
  @fused            = nil
  @personalID       = rand(2**16) | (rand(2**16) << 16)
  @hp               = 1
  @totalhp          = 1
  calc_stats
  if @form == 0 && recheck_form
    f = MultipleForms.call("getFormOnCreation", self)
    if f
      self.form = f
      reset_moves if withMoves
    end
  end
end

class SafariState
  attr_accessor :ballcount
  attr_accessor :captures
  attr_accessor :decision
  attr_accessor :steps

  def initialize
    @start      = nil
    @ballcount  = 0
    @captures   = 0
    @inProgress = false
    @steps      = 0
    @decision   = 0
  end

  def pbReceptionMap
    return @inProgress ? @start[0] : 0
  end

  def inProgress?
    return @inProgress
  end

  def pbGoToStart
    if $scene.is_a?(Scene_Map)
      pbFadeOutIn do
        $game_temp.player_transferring   = true
        $game_temp.transition_processing = true
        $game_temp.player_new_map_id    = @start[0]
        $game_temp.player_new_x         = @start[1]
        $game_temp.player_new_y         = @start[2]
        $game_temp.player_new_direction = 2
        pbDismountBike
        $scene.transfer_player
      end
    end
  end

  def pbStart(ballcount)
    @start      = [$game_map.map_id, $game_player.x, $game_player.y, $game_player.direction]
    @ballcount  = ballcount
    @inProgress = true
    @steps      = Settings::SAFARI_STEPS
  end

  def pbEnd
    @start      = nil
    @ballcount  = 0
    @captures   = 0
    @inProgress = false
    @steps      = 0
    @decision   = 0
    $game_map.need_refresh = true
  end
end

def clear
  @ballcount    = 0
  @ended        = false
  @inProgress   = false
  @decision     = 0
  @lastPokemon  = nil
  @otherparty   = []
  @contestants  = []
  @places       = []
  @start        = nil
  @contestMaps  = []
  @reception    = []
end

def inProgress?
  return @inProgress
end

